import {compare,parseMidi,validateEvents,demoEvents,reportText,noteName} from './core.js';
import {DOMAINS,defaultProfile,normalizeProfile,mediaKind,resolveWorkspace,audioEnvelope,manualAssessment,guidedReport} from './experience.js';
import * as cloud from './cloud.js';
import {createSpeechStudio} from './speech-studio.js';
import {resample} from './speech-core.js';
let speech;
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let profile=defaultProfile(),user=null,history=[],authEpoch=0,authReady=!cloud.cloudEnabled;
let state={reference:null,learner:null,result:null,demo:false,steps:[]};
let audioContext,sources=[],playing=false,stopTimer,busy=false,recorder,mediaStream,recordingSide,vision,selectedId;
const media=()=>['reference','learner'].map(s=>state[s]).filter(Boolean);
const workspace=()=>resolveWorkspace(profile,media(),$('domain').value==='auto'?null:$('domain').value);
const toast=message=>{$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('visible'),6000);};
function download(data,name,type='text/plain'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function audio(){return audioContext??=new (window.AudioContext||window.webkitAudioContext)();}
function stop(){sources.forEach(n=>{try{n.stop();}catch{}});sources=[];['reference','learner'].forEach(s=>{const v=$(s+'Video');v.ontimeupdate=null;v.pause();});clearTimeout(stopTimer);playing=false;$('playBoth').textContent='▶';}
function cleanSide(side){if(state[side]?.url)URL.revokeObjectURL(state[side].url);const v=$(side+'Video');v.ontimeupdate=null;v.pause();v.removeAttribute('src');v.load();v.classList.add('hidden');}
function changed(){speech?.invalidate();state.result=null;selectedId=null;window.speechSynthesis?.cancel();$('speak').textContent='▶ Listen to feedback';}
function setBusy(value,label='Reading recording…'){busy=value;for(const id of ['analyze','domain','newSession','editProfile','profileNav','saveProfileButton'])$(id).disabled=value;document.querySelectorAll('[data-record]').forEach(x=>x.disabled=value);$('analyze').textContent=value?label:workspace().action;}
function draw(side){
 const c=$(side+'Canvas'),ctx=c.getContext('2d');c.width=1000;c.height=480;ctx.clearRect(0,0,c.width,c.height);const item=state[side],w=workspace();
 $(side+'Stage').classList.toggle('audio-stage',item?.mediaType==='audio');
 if(item?.mediaType==='video'&&item.url)return;
 ctx.strokeStyle='#cddbc120';for(let x=45;x<980;x+=68){ctx.beginPath();ctx.moveTo(x,60);ctx.lineTo(x,350);ctx.stroke();}
 if(w.showMusic&&item?.events?.length){const notes=item.events,end=Math.max(...notes.map(e=>e.end)),low=Math.min(...notes.map(e=>e.pitch))-2,high=Math.max(...notes.map(e=>e.pitch))+2;for(const e of notes){const x=45+e.start/end*890,y=310-(e.pitch-low)/(high-low)*210,width=Math.max(6,(e.end-e.start)/end*890);ctx.fillStyle=side==='reference'?'#adc4a0':'#d8b78f';ctx.beginPath();ctx.roundRect(x,y,width,14,5);ctx.fill();ctx.fillStyle='#e1e7da';ctx.font='16px system-ui';ctx.fillText(noteName(e.pitch),x,y-10);}ctx.fillStyle='#bbceb288';ctx.font='13px system-ui';ctx.fillText('NOTE EVENTS · ORIGINAL TIMESTAMPS',45,45);return;}
 if(item?.signal?.waveform){const peaks=item.signal.waveform;ctx.fillStyle=side==='reference'?'#adc4a0':'#d8b78f';for(let i=0;i<peaks.length;i++){const height=Math.max(2,peaks[i]*230);ctx.fillRect(45+i*5.6,220-height/2,3,height);}ctx.font='14px system-ui';ctx.fillText('AUDIO WAVEFORM · '+item.duration.toFixed(1)+' SECONDS',45,60);return;}
 ctx.fillStyle='#d1dfc6';ctx.font='27px system-ui';ctx.fillText(item?'Recording ready to review':w.empty,50,180);ctx.fillStyle='#93ad91';ctx.font='18px system-ui';ctx.fillText(item?'Use playback to observe this recording.':'Your expertise begins with a single attempt.',50,220);
}
function updateSide(side){const x=state[side];$(side+'Name').textContent=x?.name||'No recording added';$(side+'Meta').textContent=x?(x.mediaType==='video'?`${x.width} × ${x.height} · video`:x.mediaType==='midi'||x.mediaType==='events'?`${x.events.length} note events · ${x.sourceLabel}`:`${x.mediaType} · ${x.sourceLabel}`):'Add audio, video, or MIDI';$(side+'Duration').textContent=x?`${x.duration.toFixed(1)} s`:'—';draw(side);}
function coachingStyle(){return {beginner:'Start with one small detail. Use a slower replay and repeat it before moving on.',intermediate:'Focus on the difference that affects your goal most. Review, adjust, and try the same passage again.',advanced:'Use focused comparisons to test consistency and refine the detail you want to improve.'}[profile.level];}
function renderSteps(){$('stepList').innerHTML=state.steps.map((s,i)=>`<label class="practice-step"><input type="checkbox" data-step="${i}" ${s.done?'checked':''}><span>${esc(s.text)}</span><button type="button" data-remove-step="${i}" aria-label="Remove step ${i+1}">×</button></label>`).join('');}
function render(){
 const w=workspace(),r=state.result,findings=r?.findings.filter(f=>f.review!=='dismissed')||[];document.body.dataset.domain=w.domain;
 $('workspaceTitle').textContent=w.title;$('workspaceSubtitle').textContent=w.subtitle;$('exerciseIcon').textContent=w.icon;$('referenceLabel').textContent=w.reference;$('learnerLabel').textContent=w.learner;
 $('profileGreeting').textContent=profile.displayName?`${profile.displayName.toUpperCase()}’S LEARNING SPACE`:'A WORKSPACE THAT LEARNS ABOUT YOU';$('profileSummary').textContent=`${DOMAINS[profile.domain].name} · ${profile.level}${profile.goal?' · '+profile.goal:''}${user?' · profile synced to your account':' · preview profile, not saved to an account'}`;
 $('editProfile').textContent='Edit my profile';$('profileAvatar').textContent=profile.displayName?profile.displayName[0].toUpperCase():'M';$('accountButton').textContent=user?'My account':'Sign in';
 $('skillChoices').classList.toggle('hidden',media().length>0);$('skillChoices').innerHTML=Object.entries(DOMAINS).filter(([k])=>k!=='general').map(([k,c])=>`<button class="skill-choice ${w.domain===k?'active':''}" data-skill="${k}"><span>${c.icon}</span>${c.name}</button>`).join('');
 $('routingInfo').textContent=`${w.reason} · ${state.demo?'synthetic example recordings':w.mediaSummary}. You can change the workspace above.`;
 $('domainNotice').textContent=w.limit;$('domainNotice').classList.toggle('hidden',w.domain==='music');$('exampleStrip').classList.toggle('hidden',!w.showMusic);
 $('phraseField').classList.toggle('hidden',!w.showPhrase);$('outlineField').classList.toggle('hidden',!w.showOutline);$('stepsField').classList.toggle('hidden',!w.showSteps);$('inspectHandsStudio').classList.toggle('hidden',!w.showHands);
 $('targetLanguage').textContent='· '+profile.language;$('toolsTitle').textContent=profile.goal||'One meaningful step at a time.';$('coachingStyle').textContent=coachingStyle();$('focusList').innerHTML=w.focus.map(t=>`<li>${esc(t)}</li>`).join('');renderSteps();
 $('musicRubric').classList.toggle('hidden',!w.showMusic);$('manualRubric').classList.toggle('hidden',w.showMusic);$('noteCategory').innerHTML=w.categories.map(c=>`<option>${esc(c)}</option>`).join('');
 $('findingCount').textContent=findings.length;$('resultStatus').textContent=r?(w.showMusic&&r.score!==null?'COMPARISON READY':(r.phoneRows?'SOUND COMPARISON':'GUIDED REVIEW')):'READY WHEN YOU ARE';$('scoreHead').textContent=w.showMusic?'Assessed dimensions':'Practice overview';$('score').classList.toggle('guided-score',!w.showMusic);
 $('score').innerHTML=w.showMusic?`${r?.score??'—'}<small>/ 100</small>`:`${findings.length} review note${findings.length===1?'':'s'}`;
 $('scoreDescription').textContent=w.showMusic?(r?.score!=null?'Notes and eligible rhythm only. Tone and technique excluded.':'Score withheld until precise, supported evidence is available.'):'Review notes describe your practice. They are not a proficiency score.';
 $('dimensions').innerHTML=w.showMusic?['notes','rhythm','tone','technique'].map(k=>`<div class="dimension"><span>${({notes:'Note accuracy',rhythm:'Timing',tone:'Tone',technique:'Technique'})[k]}</span><span class="bar"><i style="width:${r?.dimensions[k]??0}%"></i></span><b>${r?.dimensions[k]??'—'}</b></div>`).join(''):(r?.measurements||[]).map(x=>`<div class="measurement"><span>${esc(x.label)}</span><b>${esc(x.value)}</b></div>`).join('');
 $('findings').innerHTML=!r?`<div class="empty"><h3>${w.showMusic?'Your comparison starts here.':'Make room for what you want to learn.'}</h3><p>Add both recordings, then ${w.showMusic?'compare their supported details':'open a guided review and note what you observe'}.</p></div>`:findings.length?findings.map(f=>`<article class="finding ${selectedId===f.id?'selected':''}" data-finding="${esc(f.id)}"><div class="finding-main"><span class="finding-icon">${f.category==='Timing'?'◷':w.icon}</span><div><h4>${esc(f.category)}</h4><p>${esc(f.observation)}</p>${f.referenceDetail?`<div class="sound-contrast"><p>${esc(f.referenceDetail)}</p><p>${esc(f.learnerDetail)}</p></div>`:''}</div><span class="finding-status ${f.status!=='confirmed'?'possible':''}">${esc(f.status.toUpperCase())}</span></div><div class="finding-actions"><button class="timestamp" data-replay="${esc(f.id)}">▶ ${f.learner?f.learner[0].toFixed(2)+' s':'Reference '+f.reference?.[0].toFixed(2)+' s'} ↗</button><button class="review" data-review="accept" data-id="${esc(f.id)}">${f.review==='accepted'?'✓ Reviewed':'Mark reviewed'}</button><button class="review" data-review="dismiss" data-id="${esc(f.id)}">Dismiss</button></div><div class="practice-tip">↳ ${esc(f.action)}</div></article>`).join(''):`<div class="empty"><h3>${w.showMusic&&r.referenceCount?'No significant differences detected.':'Ready for a closer look.'}</h3><p>${w.showMusic&&r.referenceCount?'Only in the dimensions assessed.':'Replay both recordings. Add an observation tied to the original moments.'}</p></div>`;
 if(r)$('findings').insertAdjacentHTML('beforeend','<button id="addObservation" class="button text full">＋ Add a timestamped observation</button>');$('unassessed').innerHTML=`<span>ⓘ</span><span>${esc(r?.limitations.join(' ')||w.limit)}</span>`;
 for(const id of ['speak','downloadReport','downloadAudio','saveAttempt'])$(id).disabled=!r;
 $('speak').classList.toggle('secondary',profile.feedback==='text');$('speak').classList.toggle('primary',profile.feedback!=='text');$('downloadReport').classList.toggle('primary',profile.feedback==='text');
 $('modeBadge').textContent=state.demo?'SYNTHETIC MUSIC DEMO':'YOUR PROFILE · YOUR PRACTICE';$('sessionCount').textContent=history.length;if(!busy)$('analyze').textContent=w.action;
 for(const side of ['reference','learner'])updateSide(side);speech?.sync();
}
function resetSession(){speech?.cancel();stop();changed();for(const s of ['reference','learner']){cleanSide(s);state[s]=null;}state.demo=false;state.steps=[];$('targetPhrase').value='';$('targetOutline').value='';$('sessionTitle').value='My next practice';$('domain').value='auto';render();}
function newSession(){if(busy||recorder?.state==='recording'){toast('Finish the current recording first.');return;}resetSession();toast('Ready for your next practice.');}
function setDemo(kind){if(busy)return;resetSession();$('domain').value='music';state.demo=true;const notes=demoEvents(kind);for(const s of ['reference','learner'])state[s]={events:notes[s],mediaType:'midi',name:s==='reference'?'Reference example':'Practice example',sourceLabel:'synthetic MIDI',duration:Math.max(...notes[s].map(n=>n.end)),precise:true,warnings:[]};if(kind==='ambiguous')state.learner.warnings=['Synthetic example of insufficient recording evidence.'];$('sessionTitle').value='Music comparison example';render();assess();}
function analyzeInWorker(samples,sampleRate){return new Promise((resolve,reject)=>{const w=new Worker(new URL('./audio-worker.js',import.meta.url),{type:'module'});const t=setTimeout(()=>{w.terminate();reject(Error('Analysis timed out. Try a shorter recording.'));},90000);w.onmessage=e=>{clearTimeout(t);w.terminate();e.data.error?reject(Error(e.data.error)):resolve(e.data);};w.onerror=()=>{clearTimeout(t);w.terminate();reject(Error('The audio analysis worker could not run.'));};w.postMessage({samples,sampleRate},[samples.buffer]);});}
async function ensureNotes(item){if(item.noteAnalysisDone||['midi','events'].includes(item.mediaType))return;if(!item.samples){item.warnings=['Audio could not be decoded for note analysis. Use MIDI or a clean WAV recording.'];return;}const result=await analyzeInWorker(item.samples.slice(),12000);item.events=result.events;item.warnings=result.warnings;item.sourceLabel='experimental audio estimates';item.noteAnalysisDone=true;}
async function loadFile(side,file,durationHint=null,recorded=false){
 if(!file||busy)return;if(file.size>250*1024*1024){toast('Please use a file smaller than 250 MB.');return;}const epoch=authEpoch;let item;
 setBusy(true);stop();changed();try{
  if(state.demo){for(const s of ['reference','learner']){cleanSide(s);state[s]=null;}state.demo=false;}
  cleanSide(side);state[side]=null;const kind=mediaKind(file),buffer=await file.arrayBuffer();item={name:file.name,mediaType:kind,sourceLabel:'original recording',duration:0,events:[],precise:false,warnings:[],blob:file,recorded,hash:Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',buffer)),x=>x.toString(16).padStart(2,'0')).join('')};
  if(kind==='midi'){item.events=parseMidi(buffer);item.precise=true;item.sourceLabel='direct MIDI';item.duration=Math.max(...item.events.map(e=>e.end));}
  else if(kind==='events'){const data=JSON.parse(new TextDecoder().decode(buffer));item.events=validateEvents(Array.isArray(data)?data:data.events);item.sourceLabel='imported estimates';item.duration=Math.max(...item.events.map(e=>e.end));}
  else{
   item.url=URL.createObjectURL(file);const v=$(side+'Video');v.src=item.url;
   await new Promise((resolve,reject)=>{const clear=()=>{clearTimeout(timer);v.onloadedmetadata=null;v.onerror=null;};const timer=setTimeout(()=>{clear();reject(Error('Recording could not be opened. Try MP4 H.264/AAC or WAV.'));},12000);v.onloadedmetadata=()=>{clear();resolve();};v.onerror=()=>{clear();reject(Error('This browser cannot play that recording. Try MP4 or WAV.'));};});
   item.duration=Number.isFinite(v.duration)?v.duration:durationHint;item.width=v.videoWidth||0;item.height=v.videoHeight||0;if(!Number.isFinite(item.duration)||item.duration<=0||item.duration>60)throw Error('Use a recording up to 60 seconds long.');
   if(kind==='video')v.classList.remove('hidden');
   try{const decoded=await audio().decodeAudioData(buffer.slice(0));const off=new OfflineAudioContext(1,Math.ceil(decoded.duration*16000),16000),source=off.createBufferSource();source.buffer=decoded;source.connect(off.destination);source.start();const mono=await off.startRendering();item.speechSamples=mono.getChannelData(0).slice();item.samples=resample(item.speechSamples,16000,12000);item.signal=audioEnvelope(item.samples,12000);}catch{item.audioNotice='Audio measurements unavailable; use recording playback and manual review.';}
  }
  if(epoch!==authEpoch){if(item.url)URL.revokeObjectURL(item.url);return;}
  state[side]=item;toast(`${side==='reference'?'Reference':'Practice'} added. Workspace adapted to your profile and ${kind==='events'?'note events':kind}.`);
 }catch(error){if(item?.url)URL.revokeObjectURL(item.url);cleanSide(side);state[side]=null;toast(error.message);}finally{setBusy(false);render();}
}
async function assess(){
 if(busy)return;if(recorder?.state==='recording'){toast('Stop recording before comparing.');return;}if(!state.reference||!state.learner){toast('Add both a reference and your attempt.');return;}stop();changed();render();const epoch=authEpoch,w=workspace();setBusy(true,'Comparing recordings…');
 try{if(w.domain==='language')state.result=await speech.compare();else if(!w.showMusic)state.result=manualAssessment(w,state.reference,state.learner);else{for(const item of media())await ensureNotes(item);if(epoch!==authEpoch)return;
 const a=state.reference,b=state.learner;if(a.warnings?.length||b.warnings?.length||!a.events.length||!b.events.length){state.result=manualAssessment(w,a,b);state.result.limitations=[...(a.warnings||[]).map(x=>'Reference: '+x),...(b.warnings||[]).map(x=>'Learner: '+x),'Unable to assess notes reliably. Review the recordings manually or try direct MIDI.'];}
 else{state.result=compare(a.events,b.events,{timingTolerance:Number($('tolerance').value),allowSlower:$('allowSlower').checked,precise:a.precise&&b.precise});state.result.domain='music';}}
 if(epoch!==authEpoch)return;if(state.result){state.result.profile=structuredClone(profile);state.result.context={...practiceContext(),...(w.domain==='language'?speech.context():{})};}
 }catch(error){toast(error.message);}finally{setBusy(false);render();}
}
function practiceContext(){return {phrase:$('targetPhrase').value,outline:$('targetOutline').value,steps:structuredClone(state.steps)};}
function synth(events,from,to,speed){const ac=audio();for(const e of events){if(e.start<from-.01||e.start>to)continue;const osc=ac.createOscillator(),gain=ac.createGain();osc.type='triangle';osc.frequency.value=440*2**((e.pitch-69)/12);const at=ac.currentTime+(e.start-from)/speed+.03,d=Math.max(.03,(Math.min(e.end,to)-e.start)/speed);gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(.10,at+.01);gain.gain.exponentialRampToValueAtTime(.0001,at+d);osc.connect(gain);gain.connect(ac.destination);osc.start(at);osc.stop(at+d+.02);sources.push(osc);}}
async function play(finding=null){if(playing&&!finding){stop();return;}if(!state.reference||!state.learner){toast('Add both recordings first.');return;}stop();const heard=$('listenTo').value,speed=Number($('speed').value);await audio().resume();let maxDuration=0;for(const side of ['reference','learner']){const x=state[side],span=finding?.[side];if(finding&&!span)continue;const start=span?Math.max(0,span[0]-.3):0,end=span?Math.min(x.duration,span[1]+.6):x.duration;maxDuration=Math.max(maxDuration,(end-start)/speed);const v=$(side+'Video');if(x.url){v.currentTime=start;v.playbackRate=speed;v.muted=side!==heard;try{await v.play();}catch{toast('Playback was blocked. Use the recording’s play control.');}}else if(side===heard)synth(x.events||[],start,end,speed);}playing=true;$('playBoth').textContent='Ⅱ';stopTimer=setTimeout(stop,maxDuration*1000+100);if(finding){selectedId=finding.id;render();}}
async function record(side,button){
 if(busy)return;if(recorder?.state==='recording'){recorder.stop();return;}
 try{const video=!['language','presentation'].includes(workspace().domain);mediaStream=await navigator.mediaDevices.getUserMedia({video,audio:true});const chunks=[],epoch=authEpoch,started=performance.now();recorder=new MediaRecorder(mediaStream);recordingSide=side;
 recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{clearTimeout(record.timer);mediaStream.getTracks().forEach(t=>t.stop());button.textContent='● Record';if(epoch!==authEpoch)return;const type=recorder.mimeType,ext=type.includes('mp4')?'mp4':'webm';loadFile(side,new File(chunks,`recorded-${side}.${ext}`,{type}),Math.min(60,(performance.now()-started)/1000),true);};
 recorder.start();button.textContent='■ Stop';toast(`Recording ${video?'camera and microphone':'microphone'}. Press Stop when finished.`);record.timer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},59000);
 }catch{mediaStream?.getTracks().forEach(t=>t.stop());toast('Recording permission unavailable. Allow access or upload a file.');}
}
function report(){if(!state.result)return '';if(state.result.phoneRows)return speech.report(state.result);const r=state.result,w=workspace(),p=r.profile||profile;return `${state.demo?'SYNTHETIC DEMO — NOT A REAL PERFORMANCE\n\n':''}${w.showMusic?`Learner goal: ${p.goal||'Not specified'}\nLevel: ${p.level}\n${reportText(r,$('sessionTitle').value)}`:guidedReport(r,$('sessionTitle').value,p,practiceContext())}`;}
function speechText(){const r=state.result;if(!r)return '';const f=r.findings.filter(x=>x.review!=='dismissed');return `MIMORA. ${$('sessionTitle').value}. ${state.demo?'Synthetic example. ':''}${workspace().showMusic&&r.score!==null?`Your note and timing score is ${r.score} out of 100. `:'This practice uses guided review. No proficiency score is assigned. '}${coachingStyle()} ${f.length?f.map(x=>`${x.status==='possible'?'Possible difference. ':''}${x.observation} ${x.action}`).join(' '):workspace().showMusic&&r.referenceCount?'No significant differences were detected in assessed dimensions.':'No observations have been added yet. Replay the reference and your attempt, and note one detail to practice.'} ${r.limitations.join(' ')}`;}
function savedMedia(item){const {name,mediaType,duration,sourceLabel,events,precise,signal,width,height,hash}=item;return {name,mediaType,duration,sourceLabel,events,precise,signal,width,height,hash};}
async function saveAttempt(){
 if(!state.result)return;if(!user){openAccount();return;}if(!authReady){toast('Wait for your account to finish loading.');return;}const epoch=authEpoch;const session={id:crypto.randomUUID(),title:$('sessionTitle').value,date:new Date().toISOString(),demo:state.demo,domain:workspace().domain,profile:structuredClone(state.result.profile||profile),context:structuredClone(state.result.context||practiceContext()),result:structuredClone(state.result),reference:savedMedia(state.reference),learner:savedMedia(state.learner)};
 $('saveAttempt').disabled=true;try{await cloud.saveSession(session);if(epoch!==authEpoch)return;history.unshift(session);history=history.slice(0,30);render();toast('Report saved to your account. Original recordings stay on this device.');}catch(e){toast('Could not save: '+e.message);}finally{if(epoch===authEpoch)$('saveAttempt').disabled=!state.result;}
}
function historyView(){
 $('historySubtitle').textContent=user?'Your latest 30 saved reports, shared across your devices. Original recordings are not stored.':'Sign in to see your saved reports across devices. Guest previews are not saved.';
 $('clearHistory').disabled=!user||!history.length;$('historyList').innerHTML=history.length?history.map(x=>`<article class="history-card"><div><h3>${esc(x.title)}</h3><p>${new Date(x.date).toLocaleString()} · ${esc(DOMAINS[x.domain]?.name||x.domain)} · ${x.result.findings.filter(f=>f.review!=='dismissed').length} review notes</p></div><strong>${x.result.score??'—'}</strong><button class="button small" data-open="${esc(x.id)}">Open report</button><button class="button small text" data-delete="${esc(x.id)}">Delete</button></article>`).join(''):`<div class="empty"><h3>${user?'Your next chapter is waiting.':'Your practice, across devices.'}</h3><p>${user?'Save a practice report from the studio to see it here.':'Sign in to save your profile and reports.'}</p>${user?'':'<button class="button primary" data-account="true">Sign in</button>'}</div>`;
}
function view(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==id));document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===id));$('breadcrumb').textContent=({studio:'Practice studio',library:'My sessions',guide:'How it works'})[id];if(id==='library')historyView();window.scrollTo(0,0);}
function openProfile(domain){if(busy)return;$('profileName').value=profile.displayName;$('profileDomain').value=domain||profile.domain;$('profileLevel').value=profile.level;$('profileGoal').value=profile.goal;$('profileLanguage').value=profile.language;$('profileFeedback').value=profile.feedback;$('profileLanguageField').classList.toggle('hidden',$('profileDomain').value!=='language');$('saveProfileButton').textContent=user?'Save shared profile':'Use for this preview';$('profileSaveStatus').textContent=user?'Saved securely to your account.':'This preview is temporary. Sign in to keep your profile across devices.';$('profileDialog').showModal();}
function openAccount(){$('signInFields').classList.toggle('hidden',!!user);$('signOutButton').classList.toggle('hidden',!user);$('sendLink').disabled=!cloud.cloudEnabled;$('accountStatus').textContent=user?`Signed in as ${user.email}. Your profile and saved reports belong to this account.`:cloud.cloudEnabled?'Sign in to sync your learning profile and saved reports across devices.':'Account sign-in is being connected. You can explore a temporary profile now; cloud profiles are not available yet.';$('authMessage').textContent='';$('accountDialog').showModal();}
async function syncAccount(next){
 if(next?.id===user?.id&&authReady)return;
 const epoch=++authEpoch;authReady=false;user=next;history=[];profile=defaultProfile();if(recorder?.state==='recording')recorder.stop();resetSession();
 if(!user){authReady=true;render();historyView();return;}
 $('profileSummary').textContent='Loading your shared learning profile…';
 try{const [p,sessions]=await Promise.all([cloud.loadProfile(),cloud.loadSessions()]);if(epoch!==authEpoch)return;profile=p||defaultProfile();history=sessions;authReady=true;render();historyView();if(!p)openProfile();}catch(e){if(epoch===authEpoch){toast('Your account data could not load: '+e.message);$('profileSummary').textContent='Account data could not load. Reload to retry; no profile changes have been saved.';}}
}
async function initializeAccount(){if(!cloud.cloudEnabled)return;try{const c=await cloud.connectCloud();c.auth.onAuthStateChange((_event,session)=>{setTimeout(()=>syncAccount(session?.user||null),0);});const {data,error}=await c.auth.getSession();if(error)throw error;await syncAccount(data.session?.user||null);}catch(e){toast('Sign-in connection unavailable: '+e.message);}}
async function inspectHands(){
 const status=$('visionStatus');if(!media().some(x=>x.mediaType==='video')){toast('Add a video recording first.');return;}stop();toast('Loading optional hand inspection…');
 try{if(!vision){const {FilesetResolver,HandLandmarker}=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/vision_bundle.mjs');vision=await HandLandmarker.createFromOptions(await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm'),{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task'},runningMode:'IMAGE',numHands:2});}let count=0;for(const s of ['reference','learner']){const v=$(s+'Video');if(state[s]?.mediaType!=='video'||v.readyState<2)continue;const found=vision.detect(v),c=$(s+'Canvas'),ctx=c.getContext('2d');c.width=c.clientWidth*2;c.height=c.clientHeight*2;ctx.clearRect(0,0,c.width,c.height);const scale=Math.min(c.width/v.videoWidth,c.height/v.videoHeight),width=v.videoWidth*scale,height=v.videoHeight*scale,dx=(c.width-width)/2,dy=(c.height-height)/2;for(const hand of found.landmarks){count++;for(const point of hand){ctx.beginPath();ctx.arc(dx+point.x*width,dy+point.y*height,4,0,Math.PI*2);ctx.fillStyle='#c3eaa4';ctx.fill();}}}status.textContent=`${count} hands located. Landmarks are a visual aid, not a technique judgment.`;view('studio');toast(status.textContent);}catch{status.textContent='Hand inspection unavailable. No technique judgment has been made.';toast(status.textContent);}
}
$('profileDomain').innerHTML=Object.entries(DOMAINS).map(([k,c])=>`<option value="${k}">${c.name}</option>`).join('');
for(const id of ['profileNav','profileAvatar','editProfile'])$(id).onclick=()=>openProfile();$('accountButton').onclick=openAccount;
$('profileDomain').onchange=()=>$('profileLanguageField').classList.toggle('hidden',$('profileDomain').value!=='language');
$('profileForm').onsubmit=async e=>{e.preventDefault();if(busy)return;const next=normalizeProfile({displayName:$('profileName').value,domain:$('profileDomain').value,level:$('profileLevel').value,goal:$('profileGoal').value,language:$('profileLanguage').value,feedback:$('profileFeedback').value}),epoch=authEpoch;$('saveProfileButton').disabled=true;try{if(user){if(!authReady)throw Error('Your account data is not ready. Reload and try again.');await cloud.saveProfile(next);}if(epoch!==authEpoch)return;profile=next;$('domain').value='auto';changed();$('profileDialog').close();render();toast(user?'Profile saved across your devices.':'Preview profile applied. Sign in to save it.');}catch(error){$('profileSaveStatus').textContent=error.message;}finally{$('saveProfileButton').disabled=false;}};
$('signInForm').onsubmit=async e=>{e.preventDefault();$('sendLink').disabled=true;try{await cloud.sendSignIn($('signInEmail').value.trim());$('authMessage').textContent='Check your email for the sign-in link. Open it to return to your practice.';}catch(error){$('authMessage').textContent=error.message;}finally{$('sendLink').disabled=!cloud.cloudEnabled;}};
$('signOutButton').onclick=async()=>{try{await cloud.signOut();await syncAccount(null);$('accountDialog').close();toast('Signed out. Your cloud profile remains in your account.');}catch(e){toast(e.message);}};
$('newSession').onclick=newSession;$('analyze').onclick=assess;$('playBoth').onclick=()=>play();$('speed').onchange=stop;$('listenTo').onchange=stop;$('domain').onchange=()=>{stop();changed();render();};
$('rubricButton').onclick=()=>$('rubricDialog').showModal();$('rubricDialog').onclose=()=>{changed();render();};for(const s of ['reference','learner'])$(s+'File').onchange=e=>{loadFile(s,e.target.files[0]);e.target.value='';};
$('addStep').onclick=()=>{const text=$('stepText').value.trim();if(!text)return;if(state.steps.length>=20){toast('Keep this practice focused: up to 20 steps.');return;}state.steps.push({text,done:false});$('stepText').value='';renderSteps();};
$('stepText').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('addStep').click();}};
$('stepList').onchange=e=>{if(e.target.dataset.step!==undefined)state.steps[Number(e.target.dataset.step)].done=e.target.checked;};
$('closeNote').onclick=()=>$('noteDialog').close();$('noteForm').onsubmit=e=>{e.preventDefault();if(!state.result)return;const a=Number($('noteReference').value),b=Number($('noteLearner').value);if(a>=state.reference.duration||b>=state.learner.duration){toast('Use a timestamp inside each recording.');return;}state.result.findings.push({id:crypto.randomUUID(),category:$('noteCategory').value,status:'unverified',reference:[a,Math.min(a+1,state.reference.duration)],learner:[b,Math.min(b+1,state.learner.duration)],observation:$('noteObservation').value,action:$('noteAction').value,evidence:'Human observation linked to original recordings',method:'human-review-2.0',review:'accepted',scoringEligible:false});$('noteDialog').close();$('noteForm').reset();render();};
$('speak').onclick=()=>speech.speak(speechText());
$('downloadReport').onclick=()=>download(report(),'mimora-feedback.txt');$('downloadAudio').onclick=()=>speech.downloadFeedback();
$('saveAttempt').onclick=saveAttempt;$('inspectHands').onclick=inspectHands;$('inspectHandsStudio').onclick=inspectHands;
$('clearHistory').onclick=async()=>{if(!user||!confirm('Permanently delete your saved reports from your account?'))return;const epoch=authEpoch;try{await cloud.clearSessions();if(epoch!==authEpoch)return;history=[];historyView();render();}catch(e){toast(e.message);}};
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;if(b.dataset.close)$(b.dataset.close).close();if(b.dataset.view)view(b.dataset.view);if(b.dataset.account)openAccount();if(b.dataset.skill)openProfile(b.dataset.skill);if(b.dataset.demo)setDemo(b.dataset.demo);if(b.dataset.record)record(b.dataset.record,b);
 if(b.dataset.removeStep!==undefined){state.steps.splice(Number(b.dataset.removeStep),1);renderSteps();}
 if(b.dataset.replay)play(state.result?.findings.find(x=>x.id===b.dataset.replay));
 if(b.dataset.review&&state.result){const f=state.result.findings.find(x=>x.id===b.dataset.id);speech.invalidate();f.review=b.dataset.review==='accept'?'accepted':'dismissed';if(f.review==='dismissed'){state.result.score=null;state.result.dimensions={};state.result.limitations.push('Score withheld after review. Correct the source evidence before comparing again.');}render();}
 if(b.id==='addObservation'){$('noteReference').value=$( 'referenceVideo').currentTime||0;$('noteLearner').value=$('learnerVideo').currentTime||0;$('noteDialog').showModal();}
 if(b.dataset.open){const saved=history.find(x=>x.id===b.dataset.open);if(!saved||busy)return;resetSession();state.reference=saved.reference;state.learner=saved.learner;state.result=saved.result;state.demo=saved.demo;state.steps=saved.context?.steps||[];$('targetPhrase').value=saved.context?.phrase||'';$('targetOutline').value=saved.context?.outline||'';$('sessionTitle').value=saved.title;$('domain').value=saved.domain;view('studio');render();speech.restore(saved.context);toast('Saved report loaded. Original recordings must be reattached for video/audio replay.');}
 if(b.dataset.delete&&user){if(!confirm('Permanently delete this saved report?'))return;const epoch=authEpoch;try{await cloud.deleteSession(b.dataset.delete);if(epoch!==authEpoch)return;history=history.filter(x=>x.id!==b.dataset.delete);historyView();render();}catch(error){toast(error.message);}}
});
